def detect_intrusion(packet_log: list[dict]) -> list[dict]:
    """Identifierar misstänkta intrångsförsök via enkla heuristiker."""
    alerts = []
    ports_by_ip = defaultdict(set)
    fails_by_ip = defaultdict(int)
    count_by_ip = defaultdict(int)

    for pkt in packet_log:
        src = pkt.get("src_ip")
        if not src:
            continue
        count_by_ip[src] += 1
        if "dst_port" in pkt:
            ports_by_ip[src].add(pkt["dst_port"])
        if pkt.get("status") == "failed":
            fails_by_ip[src] += 1

    for ip, ports in ports_by_ip.items():
        if len(ports) >= 10:
            alerts.append({"src_ip": ip, "type": "port_scan",
                           "detail": f"{len(ports)} unika portar"})

    for ip, fails in fails_by_ip.items():
        if fails >= 5:
            alerts.append({"src_ip": ip, "type": "brute_force",
                           "detail": f"{fails} misslyckade försök"})

    for ip, count in count_by_ip.items():
        if count >= 100:
            alerts.append({"src_ip": ip, "type": "flood",
                           "detail": f"{count} paket"})

    return alerts
