import math
from collections import Counter
from scapy.all import rdpcap, DNS, DNSQR

def analyze_dns_traffic(pcap_file: str) -> dict:
    def entropy(s: str) -> float:
        if not s:
            return 0.0
        counts = Counter(s)
        return -sum((c / len(s)) * math.log2(c / len(s)) for c in counts.values())

    suspicious = {"dga": [], "tunneling": [], "exfiltration": []}
    query_counts = Counter()

    for pkt in rdpcap(pcap_file):
        if not (pkt.haslayer(DNS) and pkt.haslayer(DNSQR)):
            continue
        qname = pkt[DNSQR].qname.decode(errors="ignore").rstrip(".")
        if not qname:
            continue
        query_counts[qname] += 1
        labels = qname.split(".")
        domain = ".".join(labels[-2:]) if len(labels) >= 2 else qname
        longest = max(labels, key=len, default="")

        # DGA: hög entropi + lång label
        if entropy(domain.split(".")[0]) > 3.5 and len(domain.split(".")[0]) > 12:
            suspicious["dga"].append(qname)
        # Tunneling: mycket långa queries eller TXT-record
        if len(qname) > 100 or pkt[DNS].qd.qtype == 16:
            suspicious["tunneling"].append(qname)
        # Exfiltration: lång label med hög entropi (kodad data)
        if len(longest) > 40 and entropy(longest) > 4.0:
            suspicious["exfiltration"].append(qname)

    return {
        "total_queries": sum(query_counts.values()),
        "unique_domains": len(query_counts),
        "suspicious": {k: sorted(set(v)) for k, v in suspicious.items()},
        "top_queried": query_counts.most_common(10),
    }
